import React from 'react'
import Header from '../components/Header'
import { Container, Form } from 'react-bootstrap'
import background from '../images/helping.webp'
import axios from 'axios'
import { useLocation } from 'react-router-dom';

function NeedsScreen() {
  const location = useLocation();
  const { train } = location.state || {};
  const trainNo=train.train
  const handleNeeds = async (train) => {
    try {
      const response = await axios.get(`http://localhost:8000/api/getallrequest/${trainNo}/`);
      console.log(response.data)
    } catch (error) {
      console.error("There was an error deleting the item!", error);
    }
  }

  return (
    <>
      <Header/>
      <Container fluid style={{backgroundImage: `url(${background})`, backgroundRepeat: 'no-repeat', backgroundPosition: 'center', backgroundSize: 'cover', height: '100vh', opacity: 0.1}}>
        
      </Container>
    </>
  )
}

export default NeedsScreen
